INSERT INTO MES_LH_SCHEDULE_RESULT ( LH_BATCH_NO, ORDER_NO, SCHEDULE_DATE, LH_MACHINE_CODE, LH_MACHINE_NAME, LEFT_RIGHT_MOLD, MATERIAL_CODE, MES_MATERIAL_CODE, SPEC_CODE, SPEC_DESC, DAILY_PLAN_QTY, CLASS1_PLAN_QTY_SEQ, CLASS1_ANALYSIS_INPUT, CLASS1_ANALYSIS, CLASS1_PLAN_QTY, CLASS1_EXAMPLE_TYPE, CLASS1_EXAMPLE_NO, CLASS2_PLAN_QTY_SEQ, CLASS2_ANALYSIS_INPUT, CLASS2_ANALYSIS, CLASS2_PLAN_QTY, CLASS2_EXAMPLE_TYPE, CLASS2_EXAMPLE_NO, CLASS3_PLAN_QTY_SEQ, CLASS3_ANALYSIS_INPUT, CLASS3_ANALYSIS, CLASS3_PLAN_QTY, CLASS3_EXAMPLE_TYPE, CLASS3_EXAMPLE_NO, LH_TIME, DATA_VERSION, COMPANY_CODE, FACTORY_CODE, CLASS1_PLAN_TYPE, CLASS2_PLAN_TYPE, CLASS3_PLAN_TYPE ) SELECT * FROM (
SELECT #{item.lhBatchNo} AS LH_BATCH_NO, #{item.orderNo} AS ORDER_NO, #{item.scheduleDate} AS SCHEDULE_DATE, #{item.lhMachineCode} AS LH_MACHINE_CODE, #{item.lhMachineName} AS LH_MACHINE_NAME, #{item.leftRightMold} AS LEFT_RIGHT_MOLD, #{item.materialCode} AS MATERIAL_CODE, #{item.mesMaterialCode} AS MES_MATERIAL_CODE, #{item.specCode} AS SPEC_CODE, #{item.specDesc} AS SPEC_DESC, #{item.dailyPlanQty} AS DAILY_PLAN_QTY, #{item.class1PlanQtySeq} AS CLASS1_PLAN_QTY_SEQ, #{item.class1AnalysisInput} AS CLASS1_ANALYSIS_INPUT, #{item.class1Analysis} AS CLASS1_ANALYSIS, #{item.class1PlanQty} AS CLASS1_PLAN_QTY, #{item.class1ExampleType} AS CLASS1_EXAMPLE_TYPE, #{item.class1ExampleNo} AS CLASS1_EXAMPLE_NO, #{item.class2PlanQtySeq} AS CLASS2_PLAN_QTY_SEQ, #{item.class2AnalysisInput} AS CLASS2_ANALYSIS_INPUT, #{item.class2Analysis} AS CLASS2_ANALYSIS, #{item.class2PlanQty} AS CLASS2_PLAN_QTY, #{item.class2ExampleType} AS CLASS2_EXAMPLE_TYPE, #{item.class2ExampleNo} AS CLASS2_EXAMPLE_NO, #{item.class3PlanQtySeq} AS CLASS3_PLAN_QTY_SEQ, #{item.class3AnalysisInput} AS CLASS3_ANALYSIS_INPUT, #{item.class3Analysis} AS CLASS3_ANALYSIS, #{item.class3PlanQty} AS CLASS3_PLAN_QTY, #{item.class3ExampleType} AS CLASS3_EXAMPLE_TYPE, #{item.class3ExampleNo} AS CLASS3_EXAMPLE_NO, #{item.lhTime} AS LH_TIME, #{item.dataVersion} AS DATA_VERSION, #{item.companyCode} AS COMPANY_CODE, #{item.factoryCode} AS FACTORY_CODE, #{item.class1PlanType} AS CLASS1_PLAN_TYPE, #{item.class2PlanType} AS CLASS2_PLAN_TYPE, #{item.class3PlanType} AS CLASS3_PLAN_TYPE
) AS t WHERE NOT EXISTS ( SELECT 1 FROM MES_LH_SCHEDULE_RESULT WHERE LH_MACHINE_CODE = t.LH_MACHINE_CODE AND MATERIAL_CODE = t.MATERIAL_CODE AND SCHEDULE_DATE = t.SCHEDULE_DATE AND ORDER_NO = t.ORDER_NO AND DATA_VERSION = t.DATA_VERSION )

mapper.delete:
